import Spacings from '@dynatrace/strato-design-tokens/spacings';

/** Defines the available gapSizes and their mapping to the tokens. */
export const spacingProperties = {
  0: Spacings.Size0,
  2: Spacings.Size2,
  4: Spacings.Size4,
  6: Spacings.Size6,
  8: Spacings.Size8,
  12: Spacings.Size12,
  16: Spacings.Size16,
  20: Spacings.Size20,
  24: Spacings.Size24,
  32: Spacings.Size32,
  40: Spacings.Size40,
  48: Spacings.Size48,
  56: Spacings.Size56,
  64: Spacings.Size64,
};

/** Union type of the available GapSizes */
export type SpacingProperties = keyof typeof spacingProperties;

export const marginProperties = {
  ...spacingProperties,
  auto: 'auto',
};

export type MarginProperties = keyof typeof marginProperties;

